jQuery(document).ready(function($) {

    // Add button next to filter dropdowns
    var btn = $('<a/>', {
        class: 'page-title-action zhup-zhk-btn',
        text: zhaketUpdater?.translate.makeContentWithAi,
        href: zhaketUpdater?.ai_tab,
        css: {
            marginLeft: '10px'
        }
    });
    $('body.post-type-post.edit-php.post-type-post .page-title-action:not(.zhup-zhk-btn)').after(btn);



    const elements = document.querySelectorAll('.zhaket-plugin-row-notification');
    if (elements.length > 0) {
        elements.forEach(el => {
            const parentTr = el.closest('tr');
            if (parentTr) {
                const prevTr = parentTr.previousElementSibling;
                if (prevTr && prevTr.tagName.toLowerCase() === 'tr') {
                    prevTr.querySelectorAll('td').forEach(tr => {
                        tr.style.boxShadow = 'none';
                    });
                }
            }
        });
    }
});
